		public override void update()
		{
			base.update();
			if (player.y > 480)
			{
				instantDeath();
			}

			if (player.x > 300 && player.x < 660)
			{
				lens1.x = 456 + (player.x - 488) * xConstant * 0.2;
				lens1.y = 184 + (player.y - 176) * yConstant * 0.2;
				lens2.x = 456 + (player.x - 488) * xConstant * 0.4;
				lens2.y = 184 + (player.y - 176) * yConstant * 0.4;
				lens3.x = 456 + (player.x - 488) * xConstant * 0.5;
				lens3.y = 184 + (player.y - 176) * yConstant * 0.5;
				lens4.x = 456 + (player.x - 488) * xConstant * 0.8;
				lens4.y = 184 + (player.y - 176) * yConstant * 0.8;
				lens5.x = 456 + (player.x - 488) * xConstant;
				lens5.y = 184 + (player.y - 176) * yConstant;
			}
			else
			{
				lens1.x = 1480;
				lens2.x = 1480;
				lens3.x = 1480;
				lens4.x = 1480;
				lens5.x = 1480;
			}
		}

